SELECT 'gongkao', '交叉关系', 'kp-xingce-judgement-analogy-logical-intersection', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "交叉关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有的 A 是 B，有的 B 是 A。两者有交集。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、造句法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“女教师 : 青年”。有的女教师是青年，有的青年是女教师。这就是典型的交叉关系。遇到这种题，直接套用“有的...有的...”句式去验证选项。"}]}]}$$ AS jsonb), NULL, '交叉关系的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "交叉关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_logical_intersection", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
